"""Text Fingerprinting for TruthLens plagiarism detection."""
import hashlib
import random
from typing import List, Set, Tuple, Dict


class TextFingerprinter:
    """Generates text fingerprints using shingling and MinHash."""

    def __init__(self, char_n: int = 5, word_n: int = 3, num_hashes: int = 128):
        self.char_n = char_n
        self.word_n = word_n
        self.num_hashes = num_hashes
        # Generate random hash functions for MinHash
        self._max_hash = (1 << 32) - 1
        random.seed(42)
        self._hash_params = [
            (random.randint(1, self._max_hash), random.randint(0, self._max_hash))
            for _ in range(num_hashes)
        ]

    def char_ngram_shingles(self, text: str) -> Set[str]:
        """Generate character-level n-gram shingles."""
        text = text.lower().strip()
        if len(text) < self.char_n:
            return {text} if text else set()
        return {text[i:i + self.char_n] for i in range(len(text) - self.char_n + 1)}

    def word_ngram_shingles(self, text: str) -> Set[Tuple[str, ...]]:
        """Generate word-level n-gram shingles."""
        words = text.lower().split()
        if len(words) < self.word_n:
            return {tuple(words)} if words else set()
        return {
            tuple(words[i:i + self.word_n])
            for i in range(len(words) - self.word_n + 1)
        }

    def _hash_shingle(self, shingle: str) -> int:
        """Hash a shingle to a 32-bit integer."""
        return int(hashlib.md5(shingle.encode("utf-8")).hexdigest()[:8], 16)

    def minhash_signature(self, shingles: Set) -> List[int]:
        """Compute MinHash signature for a set of shingles.

        Uses the random hash function approach:
        h_i(x) = (a_i * x + b_i) mod p
        Signature[i] = min over all shingles of h_i(shingle_hash)
        """
        if not shingles:
            return [self._max_hash] * self.num_hashes

        shingle_hashes = []
        for s in shingles:
            s_str = " ".join(s) if isinstance(s, tuple) else str(s)
            shingle_hashes.append(self._hash_shingle(s_str))

        signature = []
        prime = (1 << 33) - 1  # Large prime for modular arithmetic
        for a, b in self._hash_params:
            min_hash = float("inf")
            for h in shingle_hashes:
                val = ((a * h + b) % prime) & self._max_hash
                min_hash = min(min_hash, val)
            signature.append(min_hash)

        return signature

    def estimate_similarity(self, sig1: List[int], sig2: List[int]) -> float:
        """Estimate Jaccard similarity from two MinHash signatures."""
        if len(sig1) != len(sig2):
            raise ValueError("Signatures must be the same length")
        matches = sum(1 for a, b in zip(sig1, sig2) if a == b)
        return matches / len(sig1)

    def fingerprint(self, text: str) -> Dict:
        """Generate a complete fingerprint for a text document."""
        char_shingles = self.char_ngram_shingles(text)
        word_shingles = self.word_ngram_shingles(text)
        char_sig = self.minhash_signature(char_shingles)
        word_sig = self.minhash_signature(word_shingles)
        return {
            "char_shingle_count": len(char_shingles),
            "word_shingle_count": len(word_shingles),
            "char_minhash": char_sig,
            "word_minhash": word_sig,
        }

"""Similarity Engine for TruthLens plagiarism detection."""
import math
import re
from typing import Dict, List, Tuple, Any
from collections import Counter


class SimilarityEngine:
    """Computes text similarity using multiple algorithms."""

    def _tokenize(self, text: str) -> List[str]:
        """Tokenize text into lowercase words."""
        return re.findall(r'\b[a-z]+\b', text.lower())

    def jaccard_similarity(self, set1: set, set2: set) -> float:
        """Compute Jaccard similarity between two sets."""
        if not set1 and not set2:
            return 1.0
        intersection = set1 & set2
        union = set1 | set2
        return len(intersection) / len(union) if union else 0.0

    def _build_tfidf_vectors(
        self, doc1_tokens: List[str], doc2_tokens: List[str]
    ) -> Tuple[Dict[str, float], Dict[str, float]]:
        """Build TF-IDF vectors for two documents."""
        tf1 = Counter(doc1_tokens)
        tf2 = Counter(doc2_tokens)
        all_terms = set(tf1.keys()) | set(tf2.keys())

        # IDF: log(N / df), where N=2 documents
        idf = {}
        for term in all_terms:
            df = (1 if term in tf1 else 0) + (1 if term in tf2 else 0)
            idf[term] = math.log(2 / df) if df > 0 else 0

        vec1 = {t: (tf1.get(t, 0) / max(1, len(doc1_tokens))) * idf[t] for t in all_terms}
        vec2 = {t: (tf2.get(t, 0) / max(1, len(doc2_tokens))) * idf[t] for t in all_terms}
        return vec1, vec2

    def cosine_similarity(self, text1: str, text2: str) -> float:
        """Compute cosine similarity using TF-IDF vectors."""
        tokens1 = self._tokenize(text1)
        tokens2 = self._tokenize(text2)
        if not tokens1 or not tokens2:
            return 0.0

        vec1, vec2 = self._build_tfidf_vectors(tokens1, tokens2)

        dot = sum(vec1[t] * vec2[t] for t in vec1)
        mag1 = math.sqrt(sum(v ** 2 for v in vec1.values()))
        mag2 = math.sqrt(sum(v ** 2 for v in vec2.values()))

        if mag1 == 0 or mag2 == 0:
            return 0.0
        return dot / (mag1 * mag2)

    def compare(self, text1: str, text2: str) -> Dict[str, Any]:
        """Compare two texts and return detailed similarity scores."""
        tokens1 = set(self._tokenize(text1))
        tokens2 = set(self._tokenize(text2))

        jaccard = self.jaccard_similarity(tokens1, tokens2)
        cosine = self.cosine_similarity(text1, text2)

        # Weighted combined score
        combined = 0.4 * jaccard + 0.6 * cosine

        # Determine verdict
        if combined >= 0.8:
            verdict = "High similarity - likely plagiarism"
        elif combined >= 0.5:
            verdict = "Moderate similarity - review recommended"
        elif combined >= 0.3:
            verdict = "Low similarity - likely independent"
        else:
            verdict = "No significant similarity"

        return {
            "jaccard_similarity": round(jaccard, 4),
            "cosine_similarity": round(cosine, 4),
            "combined_score": round(combined, 4),
            "shared_tokens": len(tokens1 & tokens2),
            "unique_to_text1": len(tokens1 - tokens2),
            "unique_to_text2": len(tokens2 - tokens1),
            "verdict": verdict,
        }
